def _assign_tenant(instance, tenant_ids, description):
    tenant_ids = {tenant_id for tenant_id in tenant_ids if tenant_id is not None}
    if len(tenant_ids) > 1:
        raise RuntimeError(
            f'{description} est lié à plusieurs tenants ; rattachement automatique interrompu.',
        )
    if not tenant_ids:
        raise RuntimeError(
            f'{description} ne peut pas être rattaché sans ambiguïté à un tenant.',
        )
    instance.tenant_id = tenant_ids.pop()
    instance.save(update_fields=['tenant'])


